const data = items[0].json.body.respondent;

function cleanText(text) {
  if (!text) return "";
  return String(text).replace(/\n/g, " ").replace(/\s+/g, " ").trim();
}

function formatAnswer(answer) {
  if (typeof answer !== "object") return answer;

  if (Array.isArray(answer)) return answer.join(", ");

  if (answer.phone) return `${answer.country}${answer.phone}`;

  if (answer.street) {
    return `${answer.street}, ${answer.number} - ${answer.neighborhood} - ${answer.city}/${answer.state} CEP:${answer.cep}`;
  }

  return JSON.stringify(answer);
}

let result = {};

// perguntas
data.raw_answers.forEach(item => {
  const question = cleanText(item.question.question_title);
  const answer = formatAnswer(item.answer);

  result[question] = cleanText(answer);
});

// utms
const utm = data.respondent_utms;

result.utm_source = utm.utm_source || "";
result.utm_medium = utm.utm_medium || "";
result.utm_campaign = utm.utm_campaign || "";
result.utm_term = utm.utm_term || "";
result.utm_content = utm.utm_content || "";

// transformar em STRING JSON
return [
  {
    json: {
      body: JSON.stringify(result)
    }
  }
];

const input = $('Webhook').item.json;

let data = input.body;

// se vier como string
if (typeof data === "string") {
  data = JSON.parse(data);
}

// validação
if (!data.respondent) {
  throw new Error("Não encontrei data.respondent");
}

const answers = data.respondent.answers || {};

// tradução dos campos
const fieldMap = {
  "Full name": "Nome completo",
  "WhatsApp number": "WhatsApp (com DDD)",
  "E-mail address": "E-mail",
  "Which area of your body would you like to get tattooed?":
    "Qual região do corpo você deseja tatuar?",
  "Do you already have any tattoos?":
    "Você já tem tatuagens?",
  "What’s your motivation for getting this tattoo now?":
    "Qual sua motivação para fazer essa tatuagem agora?",
  "Which of these options best describes your current moment?":
    "Qual dessas opções melhor descreve seu momento atual?",
  "Are you already familiar with the average cost of especialista’s creations, and do you feel it fits within your current reality?":
    "Você já conhece o valor médio das criações com o especialista e considera que isso está dentro da sua realidade hoje?",
  "Are you available to come to the studio in Rio de Janeiro?":
    "Você tem disponibilidade para vir até o atelier no Rio de Janeiro?",
  "How did you discover especialista’s work?":
    "Como você conheceu o trabalho do especialista?",
  "How long have you known especialista?":
    "Quanto tempo você já conhece o especialista?"
};

// tradução das regiões
const regionMap = {
  "Arm – outer shoulder": "Braço",
  "Back": "Costas",
  "Chest": "Peito",
  "Leg": "Perna",
  "Outro": "Outro"
};

const newAnswers = {};

for (const key of Object.keys(answers)) {

  const newKey = fieldMap[key] || key;

  let value = answers[key];

  // traduz região do corpo
  if (newKey === "Qual região do corpo você deseja tatuar?") {
    value = regionMap[value] || value;
  }

  newAnswers[newKey] = value;
}

// substitui answers
data.respondent.answers = newAnswers;

// retorna resultado
return [
  {
    json: {
      body: data
    }
  }
];
